// +5 episodes per city (B1 → B1+). Inserted before each week's final episode.
// Compact builders keep the data readable: scene lines [speaker, en, ru], chunks [en, ru, note].
const scene = (title, where, img, intro, lines) => ({ t: 'scene', title, where, img, intro, lines: lines.map(([s, en, ru]) => ({ s, en, ru })) });
const chunks = (title, items) => ({ t: 'chunks', title, items: items.map(([en, ru, note]) => ({ en, ru, note })) });
const g = (topic, note) => ({ t: 'grammar', topic, note });
const drake = (no, yes, ru) => ({ t: 'meme', tpl: 'drake', img: 'm_drake', no, yes, ru });
const top = (img, text, a, b) => ({ t: 'meme', tpl: 'top', img, top: text, bottom: b === undefined ? '' : a, ru: b === undefined ? a : b });
const quiz = (items) => ({ t: 'quiz', title: 'Проверь себя', items });
const C = (k, q, opts, a, why) => ({ k: 'choice', q, opts, a, why });
const F = (q, a, why) => ({ k: 'fix', q, a: [].concat(a), why });
const FL = (q, hint, a, why) => ({ k: 'fill', q, hint, a: [].concat(a), why });
const O = (ru, a) => ({ k: 'order', ru, a });
const T = (ru, a, why) => ({ k: 'type', ru, a: [].concat(a), why });
const Lz = (en, opts, a, why, v = 'm') => ({ k: 'listen', en, v, opts, a, why });
const watch = (...items) => ({ t: 'watch', items: items.map(([title, ch, why, q]) => ({ title, ch, why, q })) });
const lesson = (o) => ({ mins: 18, ...o, steps: [{ t: 'cover' }, ...o.steps] });

